package com.royaraqamia.app.shell

/**
 * Which screen a route is on (ADR-0181, decision 6).
 *
 * The site reads the same table from `shared/contracts/screens.generated.ts`, and
 * both are written from `perf/surfaces.json` by one script, so a route the matrix
 * carries cannot be placed on one client and not the other. A hand-kept copy is
 * the drift this replaces: the assistant would be told about two screens for one
 * route, and only a member would notice.
 */
data class ScreenRouteRow(
    val pattern: String,
    val surface: String,
    val product: String,
    val tab: String?,
)

/** A whole subtree one surface owns, such as the admin area. */
data class ScreenPrefixRow(
    val prefix: String,
    val surface: String,
    val product: String,
)

/** What a path resolves to, before the screen registers anything of its own. */
data class ResolvedScreen(
    val screenId: String,
    val product: String,
    val tab: String?,
)

