    val PREFIXES: List<ScreenPrefixRow> =
        listOf(
            ScreenPrefixRow("/admin", "admin", "admin"),
        )

    /**
     * The screen a route draws, or null for one the matrix does not carry.
     *
     * A tab route is tried before the plain route it shares a path with, and a
     * prefix last, so `/` is `home` until a tab says otherwise. The site resolves
     * the same path to the same id from the same rows.
     */
    fun resolve(route: String, tab: String? = null): ResolvedScreen? {
        val path = normalize(route)
        for (row in ROUTES) {
            if (row.tab != null) {
                if (path == row.pattern && tab == row.tab) {
                    return ResolvedScreen(row.surface, row.product, row.tab)
                }
                continue
            }
            if (matches(row.pattern, path)) {
                return ResolvedScreen(row.surface, row.product, null)
            }
        }
        for (row in PREFIXES) {
            if (path == row.prefix || path.startsWith("${row.prefix}/")) {
                return ResolvedScreen(row.surface, row.product, null)
            }
        }
        return null
    }

    /** `/notes/` is `/notes`; `/` stays `/`. */
    private fun normalize(route: String): String {
        val trimmed = route.trimEnd('/')
        return if (trimmed.isEmpty()) "/" else trimmed
    }

    private fun segments(path: String): List<String> =
        path.split('/').filter { it.isNotEmpty() }

    /** A dynamic segment is `[name]`, and it matches exactly one segment. */
    private fun matches(pattern: String, path: String): Boolean {
        val want = segments(pattern)
        val got = segments(path)
        if (want.size != got.size) return false
        return want.indices.all { index ->
            val part = want[index]
            (part.length >= 3 && part.startsWith("[") && part.endsWith("]")) || part == got[index]
        }
    }
